<div class="section-head"><div><span class="eyebrow">MASTER DATA</span><h2>Data Siswa</h2><p class="muted">Kelola profil dan kehadiran siswa.</p></div></div><div class="two-col"><div class="form-card"><h3>Tambah siswa</h3><form method="post"><input type="hidden" name="action" value="add_student"><label>NIS<input name="nis" required placeholder="2026010"></label><label>Nama lengkap<input name="name" required placeholder="Nama siswa"></label><div class="form-row"><label>Jenis kelamin<select name="gender"><option value="L">Laki-laki</option><option value="P">Perempuan</option></select></label><label>Kelas<select name="class_id" required><?php foreach($classes as $c): ?><option value="<?=e($c['id'])?>"><?=e($c['name'])?></option><?php endforeach;?></select><input type="hidden" name="class_name" value=""></label></div><label>Kehadiran (%)<input type="number" name="attendance_rate" min="0" max="100" step="0.01" value="90"></label><button class="btn primary" type="submit">Simpan siswa</button></form></div><div class="table-card"><div class="card-title"><h3>Daftar siswa</h3><span class="pill"><?=count($students)?> siswa</span></div><table><thead><tr><th>NIS</th><th>Nama</th><th>Kelas</th><th>Hadir</th><th>Aksi</th></tr></thead><tbody><?php foreach($students as $s): ?><tr><td><?=e($s['nis'])?></td><td><b><?=e($s['name'])?></b></td><td><?=e($s['class_name'])?></td><td><?=number_format((float)$s['attendance_rate'],0)?>%</td><td><a class="text-link" href="<?=url('profile')?>&id=<?=e($s['id'])?>">Profil</a> <form style="display:inline" method="post" onsubmit="return confirm('Hapus siswa ini?')"><input type="hidden" name="action" value="delete_student"><input type="hidden" name="id" value="<?=e($s['id'])?>"><button class="icon-btn" title="Hapus">×</button></form></td></tr><?php endforeach;?></tbody></table></div></div>